import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date').sort_index() for s in U}
# only information available at each date; forward next observed close return, no ffill of OHLC
idx=sorted(set().union(*[set(x.index) for x in D.values()])); dates=pd.DatetimeIndex(idx)
P=pd.DataFrame({s:x.close for s,x in D.items()}).reindex(dates); O=pd.DataFrame({s:x.open for s,x in D.items()}).reindex(dates); R=P.pct_change()
for w in [1,3,5,10]:
 f=-(O/P.shift(1)-1).rolling(w,min_periods=w).mean(); ics=[]; ns=[]; ds=[]; turns=[]
 for i in range(len(dates)-1):
  q=pd.concat([f.iloc[i].rename('f'),R.iloc[i+1].rename('y')],axis=1).dropna()
  if len(q)>=8:
   ics.append(spearmanr(q.f,q.y).statistic); ns.append(len(q));ds.append(dates[i])
  rr=f.iloc[i].rank(pct=True); rp=f.iloc[i-1].rank(pct=True) if i else rr; turns.append(np.nanmean(abs(rr-rp)))
 x=np.array(ics); print('w',w,'dates',len(x),'N',round(np.mean(ns),2),'coverage',round(np.mean(ns)/15,4),'IC',round(x.mean(),5),'ICIR',round(x.mean()/x.std(ddof=1),5),'hit',round(np.mean(x>0),4),'turn',round(np.nanmean(turns),4))
 for lo,hi in [(2020,2022),(2023,2024),(2025,2026)]:
  z=x[(pd.DatetimeIndex(ds).year>=lo)&(pd.DatetimeIndex(ds).year<=hi)];print(' regime',lo,hi,'IC',round(z.mean(),5),'n',len(z))
 for h in [5,10]:
  yy=P.pct_change(h).shift(-h); a=[]
  for i in range(len(dates)-h):
   q=pd.concat([f.iloc[i],yy.iloc[i].rename('y')],axis=1).dropna()
   if len(q)>=8:a.append(spearmanr(q.f,q.y).statistic)
  a=np.array(a);print(' horizon',h,'IC',round(a.mean(),5),'ICIR',round(a.mean()/a.std(ddof=1),5),'n',len(a))
# provenance artifact for best candidate
f=-(O/P.shift(1)-1).rolling(3,min_periods=3).mean();f.iloc[-1].to_csv('scripts/miner_3_20260910_gap3_signal.csv')

