 d=get_stock_daily_data(s,days=2400)
 if d is not None and len(d): px[s]=d.set_index('date')['close']
p=pd.DataFrame(px).sort_index().ffill(); r=p.pct_change(); rng=(p.diff()/p.shift()).abs(); baseline=rng.rolling(20).median();
